insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-176","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of $\\mathrm{H_2}$ is mixed with one mole of $\\mathrm{O_2}$ and sparked to form water. The reactant that is used up completely is","options":["oxygen","hydrogen","both equally","neither"],"answer_index":1,"explanation":"Water needs H$_2$ : O$_2$ = 2 : 1, so 1 mol H$_2$ is finished while 0.5 mol O$_2$ is still unused.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-177","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A flask is charged with 1 mol of $\\mathrm{N_2}$ and 1 mol of $\\mathrm{H_2}$ for the Haber reaction. Ammonia production is limited by","options":["nitrogen","hydrogen","both together","the catalyst only"],"answer_index":1,"explanation":"The 1 : 3 nitrogen-to-hydrogen requirement means 1 mol H$_2$ is exhausted long before the nitrogen.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-178","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of carbon are heated with one mole of oxygen to give only $\\mathrm{CO_2}$. The reagent that decides the amount of $\\mathrm{CO_2}$ is","options":["carbon","oxygen","neither; both finish together","the vessel volume"],"answer_index":1,"explanation":"Each mole of $\\mathrm{CO_2}$ needs 1 mol O$_2$; only 1 mol O$_2$ is supplied, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-179","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Equal molar amounts of $\\mathrm{H_2}$ and $\\mathrm{Cl_2}$ are allowed to form HCl. At the end of the reaction","options":["hydrogen remains unused","chlorine remains unused","both gases are completely consumed","no HCl forms"],"answer_index":2,"explanation":"$\\mathrm{H_2} + \\mathrm{Cl_2} \\rightarrow 2\\mathrm{HCl}$ uses the two gases in a 1 : 1 mole ratio.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-180","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Three moles of magnesium ribbon are burnt in one mole of oxygen. Formation of $\\mathrm{MgO}$ is limited by","options":["magnesium","oxygen","both equally","air moisture"],"answer_index":1,"explanation":"$2\\mathrm{Mg} + \\mathrm{O_2}$ needs Mg : O$_2$ = 2 : 1; 1 mol O$_2$ can consume only 2 mol Mg, so oxygen limits.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-181","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The quantity of product that can form in a given run is fixed by","options":["the reagent present in greater mass, always","the reagent that is consumed first","the reagent with the larger molar mass","whichever reagent is added last"],"answer_index":1,"explanation":"The limiting reagent is used up first and therefore caps the product.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-182","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"If a balanced equation is 1 : 1 and the two reactants are supplied in unequal moles, the leftover substance is","options":["always the product","the reactant that was supplied in smaller moles","the reactant that was supplied in larger moles","a catalyst"],"answer_index":2,"explanation":"The reactant present in fewer moles is limiting; the one in larger moles is excess and remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-183","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"One mole of sulphur is burnt in two moles of oxygen to give only $\\mathrm{SO_2}$. The unused oxygen at the end is","options":["0 mol","1 mol","2 mol","0.5 mol"],"answer_index":1,"explanation":"$\\mathrm{S} + \\mathrm{O_2} \\rightarrow \\mathrm{SO_2}$ uses 1 mol O$_2$, leaving 1 mol unused.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-184","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Aluminium and chlorine are mixed as 2 mol Al + 3 mol $\\mathrm{Cl_2}$ to form $\\mathrm{AlCl_3}$ ($2\\mathrm{Al} + 3\\mathrm{Cl_2} \\rightarrow 2\\mathrm{AlCl_3}$). The limiting reagent is","options":["aluminium only","chlorine only","neither; the mixture is stoichiometric","impossible to decide"],"answer_index":2,"explanation":"The supplied amounts match the 2 : 3 coefficients, so both finish together.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-185","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Four grams of hydrogen (M = 2) are sparked with 32 g of oxygen (M = 32) to form water. The mass of water that can form is","options":["18 g","36 g","16 g","4 g"],"answer_index":1,"explanation":"2 mol H$_2$ and 1 mol O$_2$ match $2\\mathrm{H_2} + \\mathrm{O_2}$; both are used and give 2 mol (36 g) of water.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-186","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A converter is loaded with 14 g of nitrogen and 6 g of hydrogen for ammonia synthesis. The reagent that runs out first is","options":["nitrogen","hydrogen","both at the same instant","neither"],"answer_index":0,"explanation":"14 g N$_2$ is 0.50 mol and would need 1.5 mol H$_2$; 6 g H$_2$ is 3.0 mol, so nitrogen is consumed first.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-187","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Twelve grams of carbon are heated with 16 g of oxygen, forming only $\\mathrm{CO_2}$. The mass of carbon dioxide obtained is","options":["22 g","28 g","44 g","16 g"],"answer_index":0,"explanation":"1.0 mol C needs 1.0 mol (32 g) O$_2$; only 0.50 mol O$_2$ is present, so 0.50 mol (22 g) of $\\mathrm{CO_2}$ forms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-188","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Eight grams of hydrogen are burnt in 32 g of oxygen. After water has formed, the unused hydrogen weighs","options":["0 g","2 g","4 g","8 g"],"answer_index":2,"explanation":"1 mol O$_2$ consumes 2 mol (4 g) H$_2$; 8 g H$_2$ was supplied, so 4 g of hydrogen remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-189","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Two moles of $\\mathrm{SO_2}$ are oxidised with two moles of $\\mathrm{O_2}$ to $\\mathrm{SO_3}$. The oxygen left unreacted is","options":["0 mol","0.5 mol","1 mol","2 mol"],"answer_index":2,"explanation":"$2\\mathrm{SO_2}$ need only 1 mol O$_2$; of the 2 mol supplied, 1 mol remains.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-190","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Marble chips (25 g $\\mathrm{CaCO_3}$, M = 100) are treated with 14.6 g of HCl (M = 36.5) according to $\\mathrm{CaCO_3} + 2\\mathrm{HCl} \\rightarrow \\mathrm{CaCl_2} + \\mathrm{H_2O} + \\mathrm{CO_2}$. The mass of $\\mathrm{CO_2}$ that can escape is","options":["4.4 g","8.8 g","11.0 g","22.0 g"],"answer_index":1,"explanation":"0.25 mol carbonate would need 0.50 mol HCl, but only 0.40 mol HCl is present, so HCl limits and $0.20$ mol (8.8 g) of $\\mathrm{CO_2}$ forms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"limiting-reagent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-191","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Theoretical yield is the mass of product calculated by assuming that","options":["the limiting reagent is completely converted as the equation is written","half the reactant is lost","no reaction occurs","the excess reagent alone reacts"],"answer_index":0,"explanation":"Theoretical yield is the stoichiometric maximum from the limiting reagent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-192","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Percentage yield is obtained from the relation","options":["(theoretical / actual) $\\times 100$","(actual / theoretical) $\\times 100$","actual $-$ theoretical","theoretical $\\times$ actual"],"answer_index":1,"explanation":"Percent yield $= (\\text{actual yield}/\\text{theoretical yield}) \\times 100$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-193","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"When the mass collected on the filter equals the mass predicted from the equation, the percentage yield is","options":["0%","50%","100%","200%"],"answer_index":2,"explanation":"Actual = theoretical gives a 100% yield.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-194","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In the school laboratory the isolated product is usually lighter than the theoretical mass because of","options":["creation of extra atoms","incomplete reaction, side products and handling losses","a change in Avogadro’s number","the law of conservation of mass being false"],"answer_index":1,"explanation":"Real recoveries suffer from incomplete conversion, competing reactions and transfer losses.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-195","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A statement that the yield is 100% means that","options":["no product was obtained","every mole of limiting reagent appeared in the isolated product as written","the excess reagent disappeared completely","the reaction was endothermic"],"answer_index":1,"explanation":"A quantitative isolation matching the stoichiometric prediction is a 100% yield.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-196","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A preparation is calculated to give 50 g of crystals; the dried crop actually weighs 40 g. The percentage yield of that run is","options":["40%","50%","80%","125%"],"answer_index":2,"explanation":"$(40/50) \\times 100 = 80\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-197","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A process is known to run at 80% yield. If the equation predicts 25 g of product, the mass a student should expect to isolate is","options":["5 g","20 g","25 g","31.25 g"],"answer_index":1,"explanation":"Actual $= 0.80 \\times 25 = 20$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-198","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Excess oxygen is used to burn 4.0 g of hydrogen. The equation predicts 36 g of water, but only 27 g is condensed. The percentage yield of water is","options":["27%","67%","75%","133%"],"answer_index":2,"explanation":"4.0 g H$_2$ is 2.0 mol and can give 2.0 mol (36 g) of water; $27/36 \\times 100 = 75\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"yield","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-199","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An uncombined free element, whether atom or molecule, is assigned an oxidation number of","options":["$+1$","$-1$","$0$","$+2$"],"answer_index":2,"explanation":"The oxidation number of an element in its elemental form is zero.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-200","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Except in peroxides, superoxides and $\\mathrm{OF_2}$, oxygen in compounds is assigned the oxidation number","options":["$-1$","$-2$","$+2$","$0$"],"answer_index":1,"explanation":"The common oxidation number of oxygen in oxides and oxo-salts is $-2$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"oxidation-number","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
